<?php
require_once __DIR__.'/../../core/api_pairing.php';
require_once __DIR__.'/../../core/db.php';
pairing_auth('financial.read');
$start=trim((string)($_GET['start_date']??date('Y-m-01')));$end=trim((string)($_GET['end_date']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end=date('Y-m-d');if($end<$start){$t=$start;$start=$end;$end=$t;}$endEx=date('Y-m-d',strtotime($end.' +1 day'));$rows=[];$guideTotal=0.0;
try{$st=db()->prepare("SELECT ph.id,ph.purchase_no,ph.purchase_date,ph.status,ph.notes header_notes,pi.id item_id,pi.item_name,pi.qty,pi.unit_cost,pi.line_total,pi.notes FROM purchase_headers ph JOIN purchase_items pi ON pi.purchase_id=ph.id LEFT JOIN suppliers s ON s.id=ph.supplier_id WHERE ph.purchase_date>=? AND ph.purchase_date<? AND ph.status<>'cancelled' AND (s.supplier_code='GENERAL_EXPENSE_SYSTEM' OR pi.item_name LIKE '[%') ORDER BY ph.purchase_date DESC,ph.id DESC,pi.id ASC");$st->execute([$start,$endEx]);foreach($st->fetchAll(PDO::FETCH_ASSOC) as $r){$type='other';if(str_starts_with((string)$r['item_name'],'[GUIDE]'))$type='guide';elseif(preg_match('/^\[([^\]]+)\]/',(string)$r['item_name'],$m))$type=strtolower($m[1]);$guide='';if(preg_match('/Guide:\s*([^|]+)/i',(string)($r['notes']??''),$m))$guide=trim($m[1]);$method='';if(preg_match('/Metode:\s*([^|]+)/i',(string)($r['notes']??''),$m))$method=trim($m[1]);$ref='';if(preg_match('/Referensi:\s*([^|]+)/i',(string)($r['notes']??''),$m))$ref=trim($m[1]);$amount=(float)$r['line_total'];if($type==='guide')$guideTotal+=$amount;$rows[]=['external_id'=>(string)$r['item_id'],'transaction_no'=>(string)$r['purchase_no'],'date'=>(string)$r['purchase_date'],'type'=>$type,'description'=>(string)$r['item_name'],'recipient'=>$guide,'payment_method'=>$method,'reference_no'=>$ref,'qty'=>(float)$r['qty'],'unit_cost'=>(float)$r['unit_cost'],'amount'=>$amount,'status'=>(string)$r['status'],'notes'=>(string)($r['notes']??'')];}}catch(Throwable $e){pairing_err('Gagal membaca pengeluaran toko: '.$e->getMessage(),500);}pairing_ok(['data'=>['start_date'=>$start,'end_date'=>$end,'guide_total'=>$guideTotal,'expense_total'=>array_sum(array_column($rows,'amount')),'rows'=>$rows]]);
